export function PayButton({ onPay }: { onPay: () => void }) {
  return (
    <div className="pay-button" onClick={onPay}>
      Pay 49.90 €
    </div>
  );
}

export function CartAnnouncer({ message }: { message: string }) {
  if (message === '') {
    return null;
  }
  return <p role="status">{message}</p>;
}

